const rejected = (message) => {
  const p = Promise.reject(new Error(message));
  p.catch(() => {});
  return p;
};
test({ sr: 'rezultati su u istom redosledu', en: 'results keep the input order' }, async () => {
  const slow = new Promise((resolve) => setTimeout(() => resolve(2), 20));
  const result = await promiseAll([Promise.resolve(1), slow, 3]);
  expect(result).toEqual([1, 2, 3]);
});
test({ sr: 'prazan niz daje prazan niz', en: 'an empty array gives an empty array' }, async () => {
  expect(await promiseAll([])).toEqual([]);
});
test({ sr: 'odbija se kad jedan promise bude odbijen', en: 'rejects when one promise rejects' }, async () => {
  await expect(promiseAll([Promise.resolve(1), rejected('boom')])).rejects.toThrow('boom');
});

