test('rejects without waiting for the others', async () => {
  let settled = false;
  const slow = new Promise((resolve) => setTimeout(() => { settled = true; resolve(1); }, 80));
  const p = promiseAll([slow, rejected('fast')]);
  await expect(p).rejects.toThrow('fast');
  expect(settled).toBe(false);
});

